// Runs the functions the compiler's DOM libraries declare, in a browser, and writes what was seen where core reads
// it. The DOM has no specification this project reads as it reads ECMAScript's: here the runs are all there is.
//
//   CHROME=/path/to/chrome node scripts/dom.mjs            runs, and writes packages/core/src/effects/dom.ts
//   CHROME=/path/to/chrome node scripts/dom.mjs --report   prints the counts, and writes nothing
//
// It needs a Chromium that runs without a window (`--headless`), which the CI does not have: the file it writes is
// kept in the repo, and regenerated by hand.
import { execFile } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readLibrary } from './library.mjs';

const here = fileURLToPath(new URL('./', import.meta.url));
const target = fileURLToPath(new URL('../../core/src/effects/dom.ts', import.meta.url));
const chrome = process.env.CHROME;
if (chrome === undefined) {
  console.error('Set CHROME to a Chromium that runs with --headless.');
  process.exit(2);
}

/** Never called: they wait for a person, leave the page, or replace the document. */
const NEVER = new Set([
  'alert', 'confirm', 'prompt', 'print', 'close', 'open', 'stop', 'Window.alert', 'Window.confirm', 'Window.prompt', 'Window.print', 'Window.close', 'Window.open', 'Window.stop',
  'Document.open', 'Document.write', 'Document.writeln', 'Document.close', 'Location.assign', 'Location.replace', 'Location.reload', 'History.back', 'History.forward', 'History.go',
  'HTMLFormElement.submit', 'HTMLFormElement.requestSubmit', 'HTMLDialogElement.showModal', 'Element.requestFullscreen', 'Element.requestPointerLock',
]);

const RUNS = 40;
const SEED = 20261011;
// The generator of values, as text a page can run: its exports become plain declarations.
const generator = readFileSync(`${here}values.mjs`, 'utf8').replaceAll(/^export /gm, '');
const page = readFileSync(`${here}dom-page.js`, 'utf8');
const work = mkdtempSync(join(tmpdir(), 'strict-ts-dom-'));

let pages = 0;
/** Runs the given functions in a page of their own. Undefined when the page gave nothing back. */
function runPage(jobs) {
  const file = join(work, `page-${pages++}.html`);
  const data = JSON.stringify(jobs).replaceAll('<', '\\u003c');
  writeFileSync(file, `<!doctype html><html><head><meta charset="utf-8"></head><body><script type="module">\nconst JOBS = ${data}; const RUNS = ${RUNS}; const SEED = ${SEED};\n${generator}\n${page}\n</script></body></html>`);
  return new Promise((resolve) => {
    execFile(chrome, ['--headless', '--no-sandbox', '--disable-gpu', '--virtual-time-budget=20000', '--dump-dom', `file://${file}`], { timeout: 45000, maxBuffer: 256 * 1024 * 1024 }, (_error, stdout) => {
      const found = /<script type="application\/json" id="strict-ts-result">([\s\S]*?)<\/script>/.exec(stdout ?? '');
      try {
        resolve(found === null ? undefined : JSON.parse(found[1].replaceAll('&lt;', '<').replaceAll('&gt;', '>').replaceAll('&amp;', '&')));
      } catch {
        resolve(undefined);
      }
    });
  });
}

/** Runs a group of functions; when the page dies, halves the group until the one that kills it is alone. */
async function run(jobs) {
  const results = await runPage(jobs);
  if (results !== undefined) return results;
  if (jobs.length === 1) return [{ name: jobs[0].name, located: true, died: true }];
  const half = Math.ceil(jobs.length / 2);
  return [...(await run(jobs.slice(0, half))), ...(await run(jobs.slice(half)))];
}

const library = readLibrary({ dom: true });
const asked = library.filter((declared) => !NEVER.has(declared.name));
// One page for the functions of each owner: what a call changes in the page stays with its owner.
const only = process.env.DOM_ONLY?.split(',');
const groups = Map.groupBy(only === undefined ? asked : asked.filter((declared) => only.includes(declared.owner)), (declared) => declared.owner);
const queue = [...groups.values()];
const observed = [];
await Promise.all(
  Array.from({ length: 6 }, async () => {
    for (let group = queue.shift(); group !== undefined; group = queue.shift()) observed.push(...(await run(group)));
  }),
);
rmSync(work, { recursive: true, force: true });

const sum = (mode, field) => Object.values(mode ?? {}).reduce((total, count) => total + count[field], 0);
const example = (mode) => Object.values(mode).find((tally) => tally.example !== undefined)?.example;
const throws = [];
const quiet = {};
const counts = { declared: library.length, neverCalled: library.length - asked.length, notFound: 0, died: 0, noCallMade: 0, threw: 0, threwOnOddValuesOnly: 0, neverThrew: 0 };
for (const result of observed.toSorted((a, b) => (a.name < b.name ? -1 : 1))) {
  if (!result.located) counts.notFound++;
  else if (result.died) counts.died++;
  else {
    const runs = sum(result.modes.plain, 'runs') + sum(result.modes.any, 'runs');
    if (runs === 0) counts.noCallMade++;
    else if (sum(result.modes.plain, 'threw') > 0) {
      counts.threw++;
      const [call, error] = example(result.modes.plain).split(' → ');
      throws.push({ name: result.name, why: `throws ${/^[AEIO]/.test(error) ? 'an' : 'a'} ${error}, as seen with ${call}`, runs, example: example(result.modes.plain) });
    } else if (sum(result.modes.any, 'threw') > 0) {
      counts.threwOnOddValuesOnly++;
      throws.push({ name: result.name, why: 'throws on a value it cannot convert: a symbol, an object without a prototype, a cycle', unprintable: true, runs, example: example(result.modes.any) });
    } else {
      counts.neverThrew++;
      quiet[result.name] = runs;
    }
  }
}

const quote = (text) => `'${text.replaceAll('\\', '\\\\').replaceAll("'", "\\'").replaceAll('\n', ' ')}'`;
const text = [
  '// Generated by packages/ledger (`CHROME=… node packages/ledger/scripts/dom.mjs`). Do not edit: change the generator.',
  '// What the functions of the DOM did when they were called in a browser on generated values. No specification was',
  '// read: a function that never threw here is not shown not to throw.',
  "import type { Ledger } from './ledger.js';",
  '',
  '/** The functions that were seen to throw. */',
  'export const domThrows: Ledger = {',
  ...throws.map((entry) => `  ${quote(entry.name)}: { verdict: 'throws', why: ${quote(entry.why)}, ${entry.unprintable ? 'unprintable: true, ' : ''}evidence: { runs: ${entry.runs}, example: ${quote(entry.example)} } },`),
  '};',
  '',
  '/** The functions that were called and never threw, with how many times. */',
  'export const domObserved: Readonly<Record<string, number>> = {',
  ...Object.entries(quiet).map(([name, runs]) => `  ${quote(name)}: ${runs},`),
  '};',
  '',
].join('\n');

if (process.argv.includes('--report')) console.log(JSON.stringify(counts, undefined, 1));
else {
  writeFileSync(target, text);
  console.log(`dom: ${throws.length} functions seen to throw, ${Object.keys(quiet).length} never threw; ${JSON.stringify(counts)}`);
}
